// middleware/reviewGuards.js
const User = require('../models/User');
const { inappropriateWords } = require('../config/moderation'); // list from README.md

const WINDOW_MS = 60_000, LIMIT = 4, MAX_REJECTIONS = 3;
const hits = new Map(); // userId -> [timestamps], shared by create + edit

const escape = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const BAD = new RegExp(`\\b(${inappropriateWords.map(escape).join('|')})\\b`, 'gi');

async function blockFlagged(req, res, next) {
  const user = await User.findById(req.user.id).select('isFlagged');
  if (!user) return res.status(401).json({ message: 'Unauthorized' });
  if (user.isFlagged) return res.status(403).json({ message: 'Account is flagged and cannot post reviews' });
  next();
}

function rateLimit(req, res, next) {
  const now = Date.now();
  const list = (hits.get(req.user.id) || []).filter((t) => now - t < WINDOW_MS);
  if (list.length >= LIMIT) {
    hits.set(req.user.id, list);
    return res.status(429).json({ message: 'Too many reviews, try again in a minute' });
  }
  list.push(now);
  hits.set(req.user.id, list);
  next();
}

async function moderate(req, res, next) {
  const text = `${req.body.title || ''} ${req.body.content || ''}`;
  const found = [...new Set((text.match(BAD) || []).map((w) => w.toLowerCase()))];
  if (!found.length) return next();
  const user = await User.findByIdAndUpdate(
    req.user.id, { $inc: { rejectedReviews: 1 } }, { new: true },
  );
  if (user.rejectedReviews >= MAX_REJECTIONS && !user.isFlagged) {
    await User.updateOne({ _id: user._id }, { isFlagged: true });
  }
  return res.status(400).json({
    message: 'Review contains inappropriate words',
    inappropriateWords: found,
    isFlagged: true,
  });
}

module.exports = { blockFlagged, rateLimit, moderate };

